const commonCues = ["第一次注意到的细节", "经常被略过的过程", "时间很紧的时候", "一件留下痕迹的小物品", "三种人的体验记录", "最容易卡住的一步"];
const places = ["深夜便利店", "社区公告栏", "小型展览", "地铁站", "教室", "周末市集", "候车大厅", "旧物仓库"];
const people = ["第一次接触的人", "每周都接触它的人", "十年后的自己", "负责维护的人", "刚好路过的人", "提出质疑的人", "用过旧版本的人"];
const forms = ["盲盒", "播客", "寻宝路线", "桌游", "旅行手册", "短纪录片", "交换日记", "博物馆导览", "一本口袋书", "声音明信片", "三格漫画"];
const constraints = ["只有五分钟", "预算为零", "只能使用手边已有的材料", "只能用声音", "没有屏幕", "只能留一项功能", "必须交给别人接着做", "只许演示一次"];
const outputs = ["一页草图", "三张便签", "一个纸样", "一段十五秒的录音", "三格分镜", "一张对照表", "一个一分钟演示", "一份问题清单"];

function matchedCues(topic) {
  return domains.find(([pattern]) => pattern.test(topic))?.[1];
}

function titleText(value, length = 27) {
  const letters = Array.from(value);
  return letters.length > length ? letters.slice(0, length).join("") + "…" : value;
}

function makeIdeas(path, batch) {
  if (path.length > 1) return makeFollowups(path, batch);

  const topic = path.at(-1).topic;
  const curated = examples.get(topic);
  if (curated && batch === 0) {
    return curated.map(([title, detail], index) => ({ ...categories[index], ...(topic === "超级个体" ? { label: "探索方向" } : {}), title, detail }));
  }

  const cues = matchedCues(topic) ?? commonCues;
  const [first, second, context, object, prototype, tradeoff] = cues;
  const short = titleText(topic);
  const quote = `「${short}」`;
  const seed = Array.from(topic).reduce((total, char) => (Math.imul(total, 31) + char.codePointAt(0)) >>> 0, 0);
  const round = curated ? batch - 1 : batch;
  const pick = (choices, salt) => choices[(seed + salt + Math.floor(round / 5)) % choices.length];
  const place = pick(places, 0);
  const person = pick(people, 2);
  const form = pick(forms, 4);
  const rule = pick(constraints, 6);
  const output = pick(outputs, 8);

  const prompts = [
    [
      [`${short}的第一印象`, `从「${first}」入手，描述你接触${quote}的第一秒。试着记录一个会被旁人错过的细节。`],
      [`闭上眼睛感受${quote}`, `只用声音、触感或气味描述它。以「${second}」为起点，看看什么特征还能被认出来。`],
      [`${short}的三格感官记录`, `分别记录接触${quote}之前、当下、之后的感受。重点留意「${first}」怎样变化。`],
      [`给${quote}配一段声音`, `用三种身边能找到的声音表现${quote}。把其中一种留给「${second}」，录下十秒试听。`],
      [`放大${quote}的一个细节`, `用「${object}」表现${quote}。把它放大到占满画面，观察原本藏起来的形状或纹理。`],
    ],
    [
      [`把${quote}带到${place}`, `想象有人在${place}第一次遇到${quote}。他原本来做什么，什么会让他停下来？`],
      [`${context}的${quote}`, `想象${context}有人需要${quote}。从「${tradeoff}」里挑一个地方改，帮助对方更快进入状态。`],
      [`${rule}时怎么办`, `把${quote}放进这个条件里，列出一个会消失的步骤，以及一个会变得更重要的步骤。`],
      [`两个人一起体验${quote}`, `设定在${place}见面。一个人主导，一个人跟随，然后交换位置，观察需求怎么变。`],
      [`${short}的一天`, `把${quote}分别放进清晨、午后和夜晚。选出最能改变原本习惯的那一刻，写出具体发生的事。`],
    ],
    [
      [`由${person}来讲`, `用${person}的口吻讲一次与${quote}的相遇。把「${object}」写成能推动故事的小线索。`],
      [`一件小物品留下的线索`, `让「${object}」成为故事的第一幕。读者要到结尾才知道它与${quote}的关系。`],
      [`一年以后回看${quote}`, `写一封来自一年后的信。信里留一条当时没注意到的细节，以及一个现在才回答得出的问题。`],
      [`同一件事，两种讲法`, `请${person}和一名旁观者讲述同一次与${quote}有关的经历，让他们对「${tradeoff}」有不同判断。`],
      [`从故事最后一幕开场`, `写下${quote}改变某件事之后的画面。回到开头，用「${first}」埋一处让结局成立的线索。`],
    ],
    [
      [`${short} × ${form}`, `借用「${form}」的一条规则来呈现${quote}。试着把「${prototype}」变成观众可以参与的部分。`],
      [`把${quote}做成${form}`, `先为${person}设计一个五分钟体验，只留下能让他们理解「${tradeoff}」的部分。`],
      [`用${form}记录${quote}`, `挑三条和${quote}有关的观察，按先后安排进「${form}」。最后留一个空位给别人的发现。`],
      [`${place}里的一次联动`, `把${quote}和${place}本来就会发生的一件事接起来。找出两件事能共用的一步。`],
      [`${form}里的隐喻`, `从${quote}和「${form}」各挑一个环节，找出它们共有的规律，再用在「${tradeoff}」上。`],
    ],
    [
      [`把${quote}的顺序倒过来`, `从结果开始往回推。找一处通常最早发生的事，把它移到最后，看前面的体验会有什么变化。`],
      [`去掉${quote}最显眼的一环`, `从「${tradeoff}」里拿掉一项，想一个保留核心体验的办法。用「${prototype}」对比前后差别。`],
      [`假设${rule}`, `重新设计一次与${quote}有关的体验。先找出哪条习惯最先被打破，再看看能否借它解决原有的麻烦。`],
      [`让新手决定怎么玩`, `让${person}重新设定${quote}的第一步。先听他会省掉什么，再看看省掉后会损失什么。`],
      [`故意让${quote}变得麻烦`, `先写出三个会让体验更糟的决定，再把其中一个反过来，看看它能否变成具体改进。`],
    ],
    [
      [`用${output}试一次`, `把${quote}变成一个可展示的小样，以「${prototype}」为起点，请朋友指出第一个让他好奇的地方。`],
      [`${short}的两种做法`, `围绕「${tradeoff}」做出两个版本，每次只改一个条件。用${output}记录别人作出选择的原因。`],
      [`给${quote}做一次五分钟访谈`, `找一个人聊聊最近一次接触它的经历。追问一句「你当时具体做了什么」，再把回答做成${output}。`],
      [`从一处小问题入手`, `观察「${tradeoff}」最容易在哪一步出问题。用${output}做一个小改动，请别人试一次。`],
      [`收集三种关于${quote}的证据`, `记录一个亲眼所见的细节、一条别人的原话和一个还没解开的问题。把它们做进${output}。`],
    ],
  ];

  return categories.map((category, index) => {
    const options = prompts[index];
    const [title, detail] = options[(round + seed + index) % options.length];
    return { ...category, title, detail };
  });
}
